Here is the commit message:
crypto: starfive - Fix memory leak in
 starfive_aes_aead_do_one_req()

The starfive_aes_aead_do_one_req() function allocates rctx->adata with
kzalloc() but fails to free it if sg_copy_to_buffer() or
starfive_aes_hw_init() fails, which lead to memory leaks.

Since rctx->adata is unconditionally freed after the write_adata
operations, ensure consistent cleanup by freeing the allocation in these
earlier error paths as well.

Compile tested only. Issue found using a prototype static analysis tool
and code review.

Fixes: 7467147ef9bf ("crypto: starfive - Use dma for aes requests")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The function `starfive_aes_aead_do_one_req()` allocates memory for `rctx->adata` using `kzalloc()`, but if either `sg_copy_to_buffer()` or `starfive_aes_hw_init()` fails, the function returns without freeing the allocated memory, causing a memory leak.

Here is the patch:

 static int starfive_aes_aead_do_one_req(struct crypto_engine *engine, void *areq)
 {
 	struct aead_request *req =
 		container_of(areq, struct aead_request, base);
 	struct starfive_cryp_ctx *ctx =
 		crypto_aead_ctx(crypto_aead_reqtfm(req));
 	struct starfive_cryp_dev *cryp = ctx->cryp;
 	struct starfive_cryp_request_ctx *rctx = aead_request_ctx(req);
 	struct scatterlist _src[2], _dst[2];
 	int ret;

 	cryp->req.areq = req;
 	cryp->assoclen = req->assoclen;
 	cryp->authsize = crypto_aead_authsize(crypto_aead_reqtfm(req));

 	rctx->in_sg = scatterwalk_ffwd(_src, req->src, cryp->assoclen);
 	if (req->src == req->dst)
 		rctx->out_sg = rctx->in_sg;
 	else
 		rctx->out_sg = scatterwalk_ffwd(_dst, req->dst, cryp->assoclen);

 	if (is_encrypt(cryp)) {
 		cryp->total_in = req->cryptlen;
 		cryp->total_out = req->cryptlen;
 	} else {
 		cryp->total_in = req->cryptlen - cryp->authsize;
 		cryp->total_out = cryp->total_in;
 		scatterwalk_map_and_copy(cryp->tag_in, req->src,
 					 cryp->total_in + cryp->assoclen,
 					 cryp->authsize, 0);
 	}

 	if (cryp->assoclen) {
 		rctx->adata = kzalloc(cryp->assoclen + AES_BLOCK_SIZE, GFP_KERNEL);
 		if (!rctx->adata)
 			return -ENOMEM;

 		if (sg_copy_to_buffer(req->src, sg_nents_for_len(req->src, cryp->assoclen),
-				      rctx->adata, cryp->assoclen) != cryp->assoclen)
+				      rctx->adata, cryp->assoclen) != cryp->assoclen) {
+			kfree(rctx->adata);
 			return -EINVAL;
+		}
 	}

 	if (cryp->total_in)
 		sg_zero_buffer(rctx->in_sg, sg_nents(rctx->in_sg),
 			       sg_dma_len(rctx->in_sg) - cryp->total_in,
 			       cryp->total_in);

 	ctx->rctx = rctx;

 	ret = starfive_aes_hw_init(ctx);
-	if (ret)
+	if (ret) {
+		if (cryp->assoclen)
+			kfree(rctx->adata);
 		return ret;
+	}

 	if (!cryp->assoclen)
 		goto write_text;

 	if ((cryp->flags & FLG_MODE_MASK) == STARFIVE_AES_MODE_CCM)
 		ret = starfive_aes_ccm_write_adata(ctx);
 	else
 		ret = starfive_aes_gcm_write_adata(ctx);

 	kfree(rctx->adata);

 	if (ret)
 		return ret;

 write_text:
 	if (!cryp->total_in)
 		goto finish_req;

 	starfive_aes_dma_init(cryp);

 	ret = starfive_aes_map_sg(cryp, rctx->in_sg, rctx->out_sg);
 	if (ret)
 		return ret;

 finish_req:
 	starfive_aes_finish_req(ctx);
 	return 0;
 }



